def minEatingSpeed(piles: list[int], h: int) -> int:
    def can_finish(speed):
        return sum(math.ceil(p / speed) for p in piles) <= h

    low, high = 1, max(piles)
    ans = high
    while low <= high:
        mid = (low + high) // 2
        if can_finish(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

